-- Objects the server needs on a clean database that the pg_dump baseline
-- (001_main.sql, regenerated by regen.sh) does not contain. Kept separate so
-- regenerating 001_main.sql does not drop them. Applied to the main database
-- by docker-init.sh.

-- Background retention-worker registry, as created by migration bundle
-- falcon-id-v0.232.250 (the GitOps repository, Keystone).
CREATE TABLE IF NOT EXISTS public.iam_data_retention_policies (
    name                     varchar(128) PRIMARY KEY,
    table_name               varchar(128) NOT NULL,
    timestamp_column         varchar(128) NOT NULL,
    retention_period_seconds bigint       NOT NULL DEFAULT 0
        CHECK (retention_period_seconds >= 0),
    additional_condition     text         NULL,
    batch_size               integer      NOT NULL DEFAULT 1000
        CHECK (batch_size >= 0),
    enabled                  boolean      NOT NULL DEFAULT true,
    registered_by_migration  varchar(64)  NOT NULL,
    created_at               timestamptz  NOT NULL DEFAULT now(),
    updated_at               timestamptz  NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_iam_data_retention_policies_enabled
    ON public.iam_data_retention_policies (name)
    WHERE enabled = true;

INSERT INTO public.iam_data_retention_policies
    (name, table_name, timestamp_column, retention_period_seconds,
     additional_condition, batch_size, registered_by_migration)
VALUES
    ('expired_iam_sessions',        'iam_sessions',        'expires_at', 604800,
     'is_active = false', 5000, 'v0.232.250'),
    ('expired_iam_password_resets', 'iam_password_resets', 'expires_at', 0,
     'used_at IS NULL', 1000, 'v0.232.250'),
    ('expired_iam_magic_links',     'iam_magic_links',     'expires_at', 0,
     'used_at IS NULL', 1000, 'v0.232.250'),
    ('old_iam_audit_logs',          'iam_audit_logs',      'created_at', 7776000,
     NULL, 1000, 'v0.232.250')
ON CONFLICT (name) DO NOTHING;
